let patients=[],view='Overview',selected=null,search='',filter='All';let state;try{state=JSON.parse(localStorage.getItem('fn-demo-v1'))||{events:[],checks:{},ack:[]}}catch{state={events:[],checks:{},ack:[]}}const $=s=>document.querySelector(s);const esc=x=>String(x??'Unknown').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const id=p=>p['Patient ID'];function save(action,patient='Workspace'){state.events.unshift({time:new Date().toISOString(),action,patient});try{localStorage.setItem('fn-demo-v1',JSON.stringify(state))}catch{alert('Storage unavailable: changes are not persisted.')}render()};const navs=['Overview','Patient assessment','Safety & process','Alert governance','Audit trail','Integration'];function go(v){view=v;render()};function badge(s){return `<span class="pill ${s==='High'?'red':s==='Unknown'?'amber':''}">${esc(s)}${s==='High'||s==='Low'?' risk':''}</span>`};function header(title,sub,action=''){return `<div class="heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`};function render(){ $('#nav').innerHTML=renderNavigation();let content='';if(view==='Overview')content=overview();if(view==='Patient assessment')content=detail();if(view==='Safety & process')content=safety();if(view==='Alert governance')content=governance();if(view==='Audit trail')content=audit();if(view==='Integration')content=integration();$('#app').innerHTML=content;}
function overview(){let high=patients.filter(p=>assess(p).risk==='High').length,mis=patients.filter(p=>assess(p).score!==p['MASCC score']||assess(p).risk!==p['Final risk group']).length;let rows=patients.filter(p=>(JSON.stringify([id(p),p.Diagnosis]).toLowerCase().includes(search.toLowerCase()))&&(filter==='All'||assess(p).risk===filter));return header('Care workspace','Recognize risk. Coordinate care. Make every step visible.',`<button class="btn primary" onclick="selected=patients[0];go('Patient assessment')">Open assessment ↗</button>`)+`<div class="banner">EDUCATIONAL PROTOTYPE · 200 synthetic cases · Draft rules require clinical validation · No automatic prescribing</div><div class="cards"><div class="card"><small>IMPORTED PATIENTS</small><b class="number">${patients.length}</b><p>Supplied MASCC workbook</p></div><div class="card"><small>HIGH-RISK PATHWAYS</small><b class="number">${high}</b><p>Recalculated from recorded inputs</p></div><div class="card"><small>LOW-RISK PATHWAYS</small><b class="number">${patients.length-high}</b><p>Not automatic discharge eligibility</p></div><div class="card"><small>WORKBOOK DISCREPANCIES</small><b class="number">${mis}</b><p>Score or final risk · review required</p></div></div><div class="layout"><section class="panel"><h2>Patient registry <span class="tag">/ ${rows.length} cases</span></h2><div class="tools"><input aria-label="Search patients" placeholder="Search patient ID or diagnosis…" value="${esc(search)}" oninput="search=this.value;refreshRows()" id="search"><select aria-label="Risk filter" onchange="filter=this.value;render()"><option ${filter==='All'?'selected':''}>All</option><option ${filter==='High'?'selected':''}>High</option><option ${filter==='Low'?'selected':''}>Low</option></select></div><div id="rows">${table(rows)}</div></section><section><div class="panel"><h2>Clinical priorities</h2><p>Actionable context, close to the decision.</p><div class="stage"><span class="dot"></span>Recognize suspected FN</div><div class="stage"><span class="dot"></span>Review instability & allergies</div><div class="stage"><span class="dot"></span>Track actual administration</div><div class="notice"><b>Time-to-antibiotic: unavailable</b><br>The workbook has no triage or administration timestamps. No baseline has been invented.</div><button class="btn" onclick="go('Safety & process')">Explore safety controls →</button></div><div class="panel" style="margin-top:18px"><h2>Knowledge status</h2><span class="pill amber">Draft · review pending</span><p style="margin-top:12px">ESMO 2016 / AHS 2014 pathway; capstone definitions reference IDSA / ASCO.</p><p>No medication doses are generated in this release.</p></div></section></div>`}
function table(rows){return `<div class="scroll"><table><thead><tr><th>Patient / diagnosis</th><th>Age</th><th>ANC ×10⁹/L</th><th>MASCC</th><th>Final pathway</th><th></th></tr></thead><tbody>${rows.slice(0,200).map(p=>{let a=assess(p);return `<tr class="pick" tabindex="0" onclick="openPatient('${id(p)}')" onkeydown="if(event.key==='Enter')openPatient('${id(p)}')"><td><span class="patient">${esc(patientName(p))}</span><div class="mini">${id(p)} · ${esc(p.Diagnosis)}</div></td><td>${p['Age (years)']}</td><td>${p['ANC (×10⁹/L)']}</td><td>${a.score??'—'}<div class="mini">${a.flags.length?'Additional risk flags':'MASCC inputs complete'}</div></td><td>${badge(a.risk)}</td><td>↗</td></tr>`}).join('')}</tbody></table></div>`};function refreshRows(){let rows=patients.filter(p=>JSON.stringify([id(p),p.Diagnosis]).toLowerCase().includes(search.toLowerCase())&&(filter==='All'||assess(p).risk===filter));$('#rows').innerHTML=table(rows)}function openPatient(pid){selected=patients.find(p=>id(p)===pid);go('Patient assessment')}
function detail(){if(!selected)return header('Patient assessment','Select a case to begin.')+`<button class="btn primary" onclick="go('Overview')">Browse patients</button>`;let p=selected,a=assess(p),pid=id(p),checks=state.checks[pid]||{};return header(pid+' · Assessment',esc(p.Diagnosis)+' / '+p['Age (years)']+' years / '+esc(p['Cancer category']),`<button class="btn" onclick="window.print()">Print summary</button>`)+`<div class="notice"><b>ALLERGY STATUS: UNKNOWN</b> · Not supplied in workbook. Verify before medication review. No order transmission is available.</div><div class="grid2"><section class="panel"><h2>Presentation & risk</h2><div class="grid2">${[['Temperature',p['Temp (°C)']+' °C'],['ANC',p['ANC (×10⁹/L)']+' ×10⁹/L'],['Systolic BP',p['Systolic BP (mmHg)']+' mmHg'],['Heart rate',p['Heart rate (bpm)']+' bpm'],['Creatinine clearance',p['CrCl (mL/min)']+' mL/min'],['Days since chemotherapy',p['Days since last chemo']]].map(([k,v])=>`<div><h3>${k}</h3><p>${esc(v)}</p></div>`).join('')}</div><h3>Recalculated MASCC: ${a.score??'Incomplete'} / 26</h3>${badge(a.risk)}<p style="margin-top:15px">Workbook score: ${p['MASCC score']} · Workbook final risk: ${p['Final risk group']}</p><h3>Decision explanation</h3><p>MASCC ${a.score>=21?'≥21':'<21'}. ${a.flags.length?esc(a.flags.join('; ')):'No additional high-risk flags detected in supplied fields.'}</p><div class="notice">FN status: ${p['Temp (°C)']>=38.3&&p['ANC (×10⁹/L)']<0.5?'numeric threshold pattern met':'requires further assessment'}. Temperature measurement method is not documented. This is a synthetic case, not a confirmed clinical diagnosis.</div></section><section class="panel"><h2>First-hour care checklist</h2><p>Manual demo documentation · no live clinical monitoring</p>${['Clinical review completed','Allergy history verified','Cultures collected / timing reviewed','Draft treatment reviewed','First dose actually administered','Reassessment documented'].map((t,i)=>`<div class="stage"><label><input type="checkbox" ${checks[i]?'checked':''} onchange="toggleCheck(${i},this.checked)"> ${t}</label>${checks[i]?`<div class="mini">${new Date(checks[i]).toLocaleString()}</div>`:''}</div>`).join('')}<div class="notice">No triage timestamp is available. Checklist timestamps reflect actions in this demo only and do not populate the clinical quality metric.</div><div class="actions"><button class="btn primary" onclick="save('Assessment reviewed','${pid}')">Record review</button><button class="btn" onclick="exportPatient()">Export case JSON</button></div></section></div><section class="panel" style="margin-top:20px"><h2>Contextual safety alerts</h2>${[...a.flags,'Allergy history missing','Medication rules awaiting pharmacist approval'].map((x,i)=>`<div class="alert"><b>${esc(x)}</b><p>${i<a.flags.length?'Review this factor alongside MASCC; score alone must not determine disposition.':'Complete the required review before generating a treatment recommendation.'}</p><button class="btn" onclick="ack('${pid}-${i}')">${state.ack.includes(pid+'-'+i)?'Acknowledged · not resolved':'Acknowledge'}</button></div>`).join('')}</section>`}
function toggleCheck(i,on){let pid=id(selected);state.checks[pid]??={};if(on)state.checks[pid][i]=new Date().toISOString();else delete state.checks[pid][i];save((on?'Completed':'Reopened')+' checklist item '+(i+1),pid)}function ack(k){if(!state.ack.includes(k)){state.ack.push(k);save('Alert acknowledged (not resolved)',id(selected))}}function download(name,data){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function exportPatient(){download(id(selected)+'-demo.json',{synthetic:true,patient:selected,assessment:assess(selected),demoChecklist:state.checks[id(selected)]||{}});save('Case exported',id(selected))}
const failures=[['Triage','Chemotherapy history missed','Visible chemotherapy history and missing-data state','Verify recognition scenario'],['Lab review','ANC units confused','Explicit ×10⁹/L label and normalized rule inputs','Unit conversion tests'],['Risk assessment','Low MASCC risk masks other hazards','Independent high-risk flags with explanation','Override test cases'],['Medication review','Allergy status unavailable','Persistent unknown-allergy banner; no dose generation','Missing allergy scenario'],['Administration','Order mistaken for delivered dose','Separate actual-administration checklist item','No order-time proxy in metric'],['Follow-up','Alert acknowledgment mistaken for resolution','Acknowledgment explicitly remains unresolved','Audit and unresolved-state review']];
function safety(){return header('Safety & process','Proactive failure analysis, connected to system controls.')+`<section class="panel"><h2>Patient journey · proposed workflow</h2><div class="grid2">${['01 · Triage → recognize possible FN','02 · Clinical assessment → check instability','03 · Laboratory → verify ANC and cultures','04 · Physician / pharmacy → review draft orders','05 · Nursing → document actual administration','06 · Treating team → reassess and follow up'].map(s=>`<div class="stage">${s}</div>`).join('')}</div></section><section class="panel" style="margin-top:20px"><h2>FMEA register · initial qualitative review</h2><p>Severity, occurrence and detectability scores require team assessment. No RPN values have been invented.</p><div class="scroll"><table><thead><tr><th>Step</th><th>What can go wrong?</th><th>System control</th><th>Verification</th></tr></thead><tbody>${failures.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')}</tbody></table></div></section><section class="panel" style="margin-top:20px"><h2>Human factors & usability</h2><div class="grid2">${['Visibility: allergy and risk remain prominent','Workflow fit: assessment follows care sequence','Consistency: stable labels and units','Cognitive load: calculated score with explanation','Error prevention: unknown remains unknown','Feedback and control: visible review and audit'].map(s=>`<div class="stage">${s}</div>`).join('')}</div><h3>Cognitive walkthrough</h3><p>Will the user know the goal, notice the action, understand its effect, and recognize progress? Evaluate assessment, allergy review and administration documentation with representative users.</p><p>Planned: think-aloud sessions, heuristic review, accessibility review and task success/time/error measurement. User testing has not yet been performed.</p></section>`}
function governance(){return header('Alert governance','Maintain relevance, ownership and review over time.')+`<div class="banner">Draft registry · clinical owners and approval dates not yet assigned</div><section class="panel"><h2>Alert registry</h2><div class="scroll"><table><thead><tr><th>Rule</th><th>Trigger</th><th>Owner</th><th>Status</th></tr></thead><tbody><tr><td>Additional high-risk feature</td><td>Recorded flag or hypotension</td><td>Oncology / ED · proposed</td><td>${badge('Unknown')}</td></tr><tr><td>Missing allergy history</td><td>Allergy data unavailable</td><td>Pharmacy · proposed</td><td>Draft</td></tr><tr><td>Medication review gate</td><td>No validated medication rules</td><td>Pharmacy / CDS committee</td><td>Active limitation</td></tr><tr><td>Delayed first dose</td><td>Needs valid triage + administration times</td><td>ED / nursing · proposed</td><td>Not enabled</td></tr></tbody></table></div><h3>Review cycle</h3><p>Clinical review → scenario testing → usability inspection → approval → monitored release → revise or retire.</p><p>Measure burden, repeat alerts, overrides and their reasons, unresolved alerts and patient-safety concerns. Acknowledgment rate alone does not establish quality.</p></section><section class="panel" style="margin-top:20px"><h2>Stakeholder power–interest grid · proposed</h2><div class="grid2">${[['Manage closely','ED & oncology leadership; clinical sponsor; medication safety'],['Keep satisfied','Executive sponsor; information security; budget owner'],['Keep involved','Bedside clinicians, nurses, pharmacists and laboratory staff'],['Monitor / consult','Other services; patient and caregiver representatives for follow-up design']].map(([h,p])=>`<div class="card"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section>`}
function audit(){return header('Audit trail','Local demonstration history. Editable browser storage, not an immutable clinical audit.',`<button class="btn" onclick="download('fn-demo-audit.json',state.events)">Export log</button>`)+`<section class="panel"><h2>Recorded activity</h2>${state.events.length?`<div class="scroll"><table><thead><tr><th>Time</th><th>Case</th><th>Event</th></tr></thead><tbody>${state.events.map(e=>`<tr><td>${esc(new Date(e.time).toLocaleString())}</td><td>${esc(e.patient)}</td><td>${esc(e.action)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No actions yet. Open a patient and record a review.</div>'}</section>`}
function integration(){return header('Integration & readiness','Transparent capabilities, with a path to a connected application.')+`<div class="grid2"><section class="panel"><h2>Available in this release</h2><div class="stage">✓ All 200 supplied synthetic cases</div><div class="stage">✓ Recalculated MASCC and risk comparison</div><div class="stage">✓ Local checklist, audit, JSON export and print</div><div class="stage">✓ Responsive interface and offline app shell</div><div class="notice">Device-local data. No cross-device sync. Installation depends on browser and hosting support.</div></section><section class="panel"><h2>Not connected yet</h2><div class="stage">○ Live EHR / laboratory / pharmacy API</div><div class="stage">○ Shared database and authenticated clinical roles</div><div class="stage">○ Background escalation or push notification</div><div class="stage">○ Validated drug and renal dose rules</div><div class="stage">○ Arabic translation and live Excel upload</div></section></div><section class="panel" style="margin-top:20px"><h2>Planned integration contracts</h2><p>Patient / Encounter → identity and visit. Observation → vitals and laboratory results. AllergyIntolerance → allergy history. MedicationRequest / MedicationAdministration → distinguish ordering from administration. AuditEvent → server-side audit.</p><p>These are proposed mappings, not live endpoints. Backend authentication, clinical rule approval and integration testing are required before deployment in a hospital.</p><button class="btn" onclick="download('fn-integration-contract.json',{status:'planned-not-connected',resources:['Patient','Encounter','Observation','AllergyIntolerance','MedicationRequest','MedicationAdministration','AuditEvent']})">Export proposed contract</button></section>`}
document.addEventListener('DOMContentLoaded',()=>fetch('patients.json').then(r=>r.json()).then(p=>{patients=p;render()}).catch(()=>{$('#app').innerHTML='<div class="notice">Patient data could not load. Reconnect and refresh.</div>'}));if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});

function renderNavigation(){
 const groups=[['Clinical workspace',[['Team workspace','Connected demo','M3 8h18v13H3z M8 8V3h8v5 M12 11v7 M8.5 14.5h7'],['Overview','Overview','M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z'],['Patient assessment','Patient assessment','M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M20 8v6 M17 11h6'],['Integration','Results & integration','M9 3h6 M10 3v7L4 20h16l-6-10V3 M8 15h8'],['Escalation center','Escalation center','M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4']]],['Quality and value',[['Safety & process','Safety & process','M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6'],['Clinical quality','Clinical quality','M3 17l6-6 4 4 8-10 M3 3v18h18'],['Financial impact','Financial impact','M4 21V11h4v10 M10 21V7h4v14 M16 21V3h4v18']]],['Governance',[['Alert governance','Alert governance','M12 3l9 17H3z M12 9v4 M12 16v1'],['Audit trail','Audit trail','M8 3h12v18H4V7z M8 3v4H4 M8 11h8 M8 15h8'],['Scope & evidence','Scope & evidence','M12 5C8 2 3 3 3 3v16s5-1 9 2c4-3 9-2 9-2V3s-5-1-9 2z M12 5v16']]]];
 return groups.map(([label,items])=>`<div class="nav-group-label">${label}</div>${items.map(([route,title,path])=>`<button class="${view===route?'active':''}" ${view===route?'aria-current="page"':''} onclick="go('${route}')"><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg><span>${title}</span></button>`).join('')}`).join('');
}
